import json,datetime,hashlib,os,sys
from pathlib import Path
from collections import Counter,defaultdict
sys.dont_write_bytecode=True
O=Path(__file__).resolve().parent;D=O.parent;R=O.parents[3]
def load(name):return json.loads((O/name).read_text())
def rows(p):return [json.loads(l) for l in Path(p).read_text().splitlines() if l.strip()]
def save(n,x):(O/n).write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def table(h,rr):
 def cell(x):return str(x).replace('|','\\|').replace('\n','<br>')
 return '\n'.join(['| '+' | '.join(map(cell,h))+' |','| '+' | '.join(['---']*len(h))+' |']+['| '+' | '.join(map(cell,r))+' |' for r in rr])
def arrow(b,a):return f'{b} → {a}'
def nscore(x):return f"{x['agreement']}/{x['n']}"
def err(x):return '/'.join(str(x[k]) for k in ('FP','FN','UNC'))
def ferr(x):return f"{x['fd']}/{x['fk']} (total {x['total']}; objective n={x['objective_n']}; population n={x['n']}; blind kept {x['blind_kept']}/{x['blind_n']})"
def f(x):return f'{x:.8g}' if isinstance(x,float) else x
